import os
import random
import argparse
import shutil
import glob

def cleanup_files():
    """Remove existing files generated by previous runs."""
    file_patterns = ["sim*", "dst*", "sig*", "test_*", "*sub*"]
    for pattern in file_patterns:
        os.system(f"rm {pattern}")

def get_random_numbers(array_length, max_value):
    """Generate a list of unique random numbers."""
    if array_length > max_value:
        raise ValueError("array_length must be less than or equal to max_value")
    return random.sample(range(max_value), array_length)

def generate_simulation_and_reconstruction_scripts(dec_files, num_jobs, events_per_job):
    """Generate simulation and reconstruction scripts for each .dec file."""
    random_numbers = get_random_numbers(num_jobs, 99999)
    for dec_file in dec_files:
        dec_name = os.path.splitext(dec_file)[0]
        for i in range(num_jobs):
            # Create simulation script
            with open(f"sim_{dec_name}_{i}", "w") as sim_script, open("msim.txt", "r") as sim_template:
                content = sim_template.read().replace("aaaa", dec_name).replace("pid", f"{dec_name}_{i}")\
                                              .replace("NUMBER", str(random_numbers[i]))\
                                              .replace("SIMN", str(events_per_job))
                sim_script.write(content)

            # Create reconstruction script
            with open(f"dst_{dec_name}_{i}", "w") as dst_script, open("mdst.txt", "r") as dst_template:
                content = dst_template.read().replace("NUMBER", str(random_numbers[i]))\
                                              .replace("pid1", f"{dec_name}_{i}")
                dst_script.write(content)

        # Add job to submission file
        with open("sub", "a") as submission_file:
            if num_jobs == 1:
                submission_file.write(f"boss.condor  sim_{dec_name}_0 dst_{dec_name}_0\n")
            else:
                submission_file.write(f"boss.condor -n {num_jobs} sim_{dec_name}_\"%{{ProcId}}\" dst_{dec_name}_\"%{{ProcId}}\"\n")

    # Make submission file executable
    os.system("chmod +x sub")

def generate_signal_scripts(dec_files, nDataFile):
    """Generate signal scripts for each .dec file."""
    for decfile in dec_files:
        if decfile.endswith(".dec"):
            decname = os.path.splitext(decfile)[0]
            dst_files = [f for f in os.listdir() if f.startswith(decname) and f.endswith(".dst")]
            dst_files = sorted(dst_files)
            fileNumber = len(dst_files)
            iJob = 0
            n = 0

            for dstfile in dst_files:
                m = n + 1
                line = f'"{dstfile}"'

                if n % nDataFile == 0:
                    if os.path.exists(f"sig_{decname}_{iJob}"):
                        with open(f"job.foot", "r") as foot_file, open(f"sig_{decname}_{iJob}", "a") as sig_file:
                            content = foot_file.read().replace("456", f"{decname}_{iJob}")
                            sig_file.write(content)
                        iJob += 1

                    with open(f"sig_{decname}_{iJob}", "w") as sig_file, open(f"job.head", "r") as head_file:
                        content = head_file.read()
                        sig_file.write(content)

                with open(f"sig_{decname}_{iJob}", "a") as sig_file:
                    if m % nDataFile == 0 or m == fileNumber:
                        sig_file.write(line + "\n")
                    else:
                        sig_file.write(line + ",\n")
                n += 1

            with open(f"job.foot", "r") as foot_file, open(f"sig_{decname}_{iJob}", "a") as sig_file:
                content = foot_file.read().replace("456", f"{decname}_{iJob}")
                sig_file.write(content)

            jobname = [f for f in os.listdir() if f.startswith(f"sig_{decname}_")]
            job_amount = len(jobname)

            with open("sigsub", "a") as sigsub_file:
                if job_amount == 1:
                    sigsub_file.write(f"boss.condor  sig_{decname}_0\n")
                else:
                    sigsub_file.write(f"boss.condor -n {job_amount} sig_{decname}_\"%{{ProcId}}\"\n")

    # Make submission file executable
    os.system("chmod +x sigsub")

def generate_directories(ecmlist, files_to_copy, ecmenergy, runlist):
    """
    Generate directories for each name in the ecmlist and copy specified files into them,
    also generate custom msim.txt and .dec files based on templates.

    :param ecmlist: List of names for which to create directories
    :param files_to_copy: List of file names to copy into each created directory
    :param ecmenergy: List of ECM energies corresponding to each directory
    :param runlist: List of run numbers corresponding to each directory
    """
    # Get all .dec template files
    dec_templates = glob.glob('*.dec')

    for i, name in enumerate(ecmlist):
        # Create a directory for this name
        dir_name = f"{name}"
        os.makedirs(dir_name, exist_ok=True)

        # Modify and copy files
        for file_path in files_to_copy:
            file_name = os.path.basename(file_path)
            dst = os.path.join(dir_name, file_name)
            # Check if the file is a .dec file and needs to be modified
            if file_path.endswith('.dec'):
                if os.path.exists(file_path):
                    with open(file_path, "r") as src_file, open(dst, "w") as dst_file:
                        content = src_file.read().replace("ECMS", str(ecmenergy[i]))
                        dst_file.write(content)
                else:
                    print(f"DEC template file {file_path} does not exist. It has not been copied.")
            elif file_path == 'msim.txt':
                # Special handling for msim.txt if it's in the files_to_copy
                with open(file_path, "r") as src_file, open(dst, "w") as dst_file:
                    content = src_file.read().replace("RUNNO", str(runlist[i]))
                    dst_file.write(content)
            else:
                # Copy other files without modification
                if os.path.exists(file_path):
                    shutil.copy(file_path, dst)
                else:
                    print(f"File {file_path} does not exist. It has not been copied.")

def main():
    parser = argparse.ArgumentParser(description="A script to generate simulation, reconstruction, and signal scripts.")
    parser.add_argument("--createdir", action="store_true", help="Create the sub ecm directories")
    parser.add_argument("--simulate", action="store_true", help="Generate simulation and reconstruction scripts")
    parser.add_argument("--signal", action="store_true", help="Generate signal scripts")
    parser.add_argument("--cleanup", action="store_true", help="Clean up existing files")
    args = parser.parse_args()

    if not any(vars(args).values()):
        parser.print_help()
        return

    if args.cleanup:
        cleanup_files()

